css_raw:
:root {
  --space-0: 0px; --space-1: 4px; --space-2: 8px; --space-3: 16px;
  --space-4: 24px; --space-5: 32px; --space-6: 48px; --space-7: 64px;

  --radius-sm: 4px; --radius-md: 8px; --radius-lg: 12px; --radius-xl: 16px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(15,23,42,.06), 0 1px 1px rgba(15,23,42,.04);
  --shadow-md: 0 4px 12px rgba(15,23,42,.08), 0 1px 3px rgba(15,23,42,.06);
  --shadow-lg: 0 16px 40px rgba(15,23,42,.12), 0 4px 12px rgba(15,23,42,.06);

  --duration-fast: 160ms; --duration-base: 240ms; --duration-slow: 360ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);

  --text-body: clamp(16px, 0.2vw + 15.4px, 16px);
  --text-lead: clamp(18px, 0.6vw + 16px, 20px);
  --text-h3: clamp(21px, 1.2vw + 17px, 25px);
  --text-h2: clamp(24px, 1.8vw + 18px, 31px);
  --text-h1: clamp(28px, 2.6vw + 18px, 39px);
  --text-display: clamp(32px, 3.4vw + 18px, 49px);
  --text-hero: clamp(37px, 4.2vw + 18px, 61px);

  --container: 1280px;
  --gutter: var(--space-3);
  --section-y: clamp(48px, 8vw, 64px);
  --touch: 44px;

  /* Sémantique partagée — chaque niche définit color-action / on-action / accent
     dans son bloc [data-theme="{slug}"] ci-dessous ou injecté à la génération. */
  --bg: var(--color-surface);
  --bg-elevated: var(--color-surface-alt);
  --fg: var(--color-text);
  --fg-muted: var(--color-text-muted);
  --action: var(--color-action);
  --action-hover: var(--color-action-hover);
  --on-action: var(--color-on-action);
  --border: var(--color-border);
  --focus-ring: 0 0 0 3px color-mix(in srgb, var(--action) 45%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-fast: 1ms; --duration-base: 1ms; --duration-slow: 1ms;
  }
  *, *::before, *::after {
    animation-duration: 1ms !important;
    transition-duration: 1ms !important;
    scroll-behavior: auto !important;
  }
}

/* Exemple d'injection par niche (le générateur copie ce bloc avec les valeurs
   de niches/{slug}.json — jamais de hex écrit ailleurs dans le code généré) */
[data-theme="saas"] {
  --color-primary: #0B1F3A;
  --color-action: #1D4ED8;
  --color-action-hover: #1E40AF;
  --color-on-action: #FFFFFF;
  --color-accent: #3B82F6; /* hover/icône/chart only, jamais bouton/texte */
  --color-surface: #F1F5F9;
  --color-surface-alt: #FFFFFF;
  --color-text: #0B1F3A;
  --color-text-muted: #475569;
  --color-border: #E2E8F0;
  --font-display: Inter, system-ui, sans-serif;
  --font-body: Inter, system-ui, sans-serif;
  --radius-control: 8px;
  --radius-card: 12px;
  --radius-image: 12px;
}
